INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "晋王十二月壬戌到胡柳陂，梁军随后追至。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：三万白丁为主书所记营栅役夫，不当作三万骑兵；战斗始于癸亥。", "status": "draft", "id": "02bed710-b205-5994-b9b3-0093a59db35f", "subject_id": "d8e04950-0ef6-5ec6-bb81-77b9097504b0", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "918年十二月壬戌到胡柳陂；癸亥旦知梁军到", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：主书本段未明标月日；他书记载作独立引文，不覆盖主书。", "status": "draft", "id": "1daf2486-c99e-5f31-874a-e2f1c9f0dc44", "subject_id": "d8e04950-0ef6-5ec6-bb81-77b9097504b0", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记贺瑰：弃梁营追晋军者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "86f5106b-b44e-5817-8d27-cb677f8c0708", "subject_id": "767516dc-02aa-5314-8b4b-b5be06aaa9bd", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "贺瑰：弃梁营追晋军者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "461fbee1-66d0-577c-b45d-3c8267a6b968", "subject_id": "6c2d343a-acdb-5b5b-9886-669cf0683d3b", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存勖：率军至胡柳陂者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "4b45d61b-375c-5306-8fa5-4d4311f77522", "subject_id": "4e068da9-c8dd-5a31-a747-87669e3bf993", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "晋王：率军至胡柳陂者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：贺瑰闻晋王已西，亦弃营而踵之。晋王发魏博白丁三万从军，以供营栅之役，所至，营栅立成。壬戌，至胡柳陂。癸亥旦，候者言梁兵自后至矣。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c21387ce-302a-59e0-9093-4738024f813d", "subject_id": "71e72766-e545-5e9b-a65b-962444b6f100", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》卷二十八记晋军癸亥至胡柳坡，与主书壬戌至有一日差异。", "citation": "《旧五代史》卷二十八，段落 jiu-wudaishi-205deb4a7860-p000940；EPUB电子本，纸本及异文待核", "note": "原文：癸亥，次胡柳坡。遲明，梁軍亦至；核对说明：主书壬戌至、癸亥交战；旧书癸亥至、迟明梁军到。暂保留两书日次。", "status": "draft", "id": "40813314-bba7-58e6-9af3-797c6437bac0", "subject_id": "d8e04950-0ef6-5ec6-bb81-77b9097504b0", "source_id": "ffbca32a-fecf-55e5-bc7f-00c2722bae7f"}, {"subject_table": "event", "field_path": "description", "claim_text": "周德威劝晋王持营待梁军疲，晋王未采纳。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：周德威曰：“贼倍道而来，未有所舍，我营栅已固，守备有馀，既深入敌境，动须万全，不可轻发。此去大梁至近，梁兵各念其家，内怀愤激，不以方略制之，恐难得志。王宜按兵勿战，德威请以骑兵扰之，使彼不得休息，至暮营垒未立，樵爨未具，乘其疲乏，可一举灭也。”王曰：“前在河上恨不见贼，今贼至不击，尚复何待，公何怯也！”顾李存审曰：“敕辎重先发，吾为尔殿后，破贼而去！”即以亲军先出。；核对说明：周德威建议来自本段前文，此句体现晋王不从；不把辎重先发写成已安全撤离。", "status": "draft", "id": "ba8cea6e-d7e0-54ca-b3be-74f65a6ae4a7", "subject_id": "2c710144-61c7-5d0a-a257-6e1f22961d7a", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "918年十二月癸亥战前", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：周德威曰：“贼倍道而来，未有所舍，我营栅已固，守备有馀，既深入敌境，动须万全，不可轻发。此去大梁至近，梁兵各念其家，内怀愤激，不以方略制之，恐难得志。王宜按兵勿战，德威请以骑兵扰之，使彼不得休息，至暮营垒未立，樵爨未具，乘其疲乏，可一举灭也。”王曰：“前在河上恨不见贼，今贼至不击，尚复何待，公何怯也！”顾李存审曰：“敕辎重先发，吾为尔殿后，破贼而去！”即以亲军先出。；核对说明：主书本段未明标月日；他书记载作独立引文，不覆盖主书。", "status": "draft", "id": "7c9c7de8-ef67-5761-8f09-7ee2ae5c5764", "subject_id": "2c710144-61c7-5d0a-a257-6e1f22961d7a", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记周德威：劝持营待梁军疲者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：周德威曰：“贼倍道而来，未有所舍，我营栅已固，守备有馀，既深入敌境，动须万全，不可轻发。此去大梁至近，梁兵各念其家，内怀愤激，不以方略制之，恐难得志。王宜按兵勿战，德威请以骑兵扰之，使彼不得休息，至暮营垒未立，樵爨未具，乘其疲乏，可一举灭也。”王曰：“前在河上恨不见贼，今贼至不击，尚复何待，公何怯也！”顾李存审曰：“敕辎重先发，吾为尔殿后，破贼而去！”即以亲军先出。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "f127a59c-9b0f-5752-8398-df954c5760f4", "subject_id": "78a7d664-601e-54e7-852f-67032f549cde", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周德威：劝持营待梁军疲者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：周德威曰：“贼倍道而来，未有所舍，我营栅已固，守备有馀，既深入敌境，动须万全，不可轻发。此去大梁至近，梁兵各念其家，内怀愤激，不以方略制之，恐难得志。王宜按兵勿战，德威请以骑兵扰之，使彼不得休息，至暮营垒未立，樵爨未具，乘其疲乏，可一举灭也。”王曰：“前在河上恨不见贼，今贼至不击，尚复何待，公何怯也！”顾李存审曰：“敕辎重先发，吾为尔殿后，破贼而去！”即以亲军先出。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "2856e6a9-7482-5e74-9ec8-e409f2e0eb05", "subject_id": "a75fac43-d31c-5281-8238-bf8bdfcc753c", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "晋王：拒周德威缓战建议并率亲军先出者。", "citation": "卷270·贞明四年（918）·zztj-v270-y0918-p039·原文件第66行", "note": "原文：周德威曰：“贼倍道而来，未有所舍，我营栅已固，守备有馀，既深入敌境，动须万全，不可轻发。此去大梁至近，梁兵各念其家，内怀愤激，不以方略制之，恐难得志。王宜按兵勿战，德威请以骑兵扰之，使彼不得休息，至暮营垒未立，樵爨未具，乘其疲乏，可一举灭也。”王曰：“前在河上恨不见贼，今贼至不击，尚复何待，公何怯也！”顾李存审曰：“敕辎重先发，吾为尔殿后，破贼而去！”即以亲军先出。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c8654616-4062-5b51-a79c-5a5b7cf8d5b9", "subject_id": "02f0decd-bf62-5516-9615-ef1e3ee58ff2", "source_id": "b0608244-0466-5cc9-a4ff-60479b6d2677"}, {"subject_table": "person", "field_path": "d